<?php
namespace App\Http\Controllers;use App\Models\{AdvancePayment,Employee,Project};use Illuminate\Http\Request;class AdvancePaymentController extends Controller{function index(){return view('crud.index',['title'=>'Advance Payments','items'=>AdvancePayment::with('employee','project')->latest()->paginate(30),'type'=>'advance-payments']);}function create(){return view('payments.form',['item'=>new AdvancePayment,'employees'=>Employee::all(),'projects'=>Project::all(),'route'=>'advance-payments']);}function store(Request $r){AdvancePayment::create($r->validate(['employee_id'=>'required','project_id'=>'nullable','amount'=>'required|numeric|min:0.01','payment_date'=>'required|date','payment_type'=>'required','remarks'=>'nullable']));return redirect()->route('advance-payments.index')->with('success','Saved');}function show(AdvancePayment $advancePayment){return view('crud.show',['item'=>$advancePayment]);}function edit(AdvancePayment $advancePayment){return view('payments.form',['item'=>$advancePayment,'employees'=>Employee::all(),'projects'=>Project::all(),'route'=>'advance-payments']);}function update(Request $r,AdvancePayment $advancePayment){$advancePayment->update($r->all());return redirect()->route('advance-payments.index')->with('success','Updated');}function destroy(AdvancePayment $advancePayment){$advancePayment->delete();return back();}}
